writer.write(uint8);
writer.close();
const reader = ds.readable.getReader();
let chunks = [];
while(true) {
  const {done, value} = await reader.read();
  if(done) break;
  chunks.push(value);
}
// concatenate all chunks
let total = chunks.reduce((acc, c) => acc + c.length, 0);
