md`# duo-fmt@1.0.0 — vendored

The \`stamp(n)\` and \`VERSION\` exports from [duo-fmt](https://eval.test/npm/duo-fmt@1.0.0) run offline via the rewrite route (§ 3 of the vendoring wiki).`
)};

const _padBlobUrl = async function padBlobUrl(FileAttachment){return(
  (() => {
    const blob = new Blob(
      [await FileAttachment("pad.js").text()],
      { type: "text/javascript" }
    );
    return URL.createObjectURL(blob);
  })()
)};

const _entryBlobUrl = async function entryBlobUrl(FileAttachment, padBlobUrl){return(
  (() => {
    const src = await FileAttachment("index.js").text();
    const patched = src.replace('"./pad.js"', JSON.stringify(padBlobUrl));
    const blob = new Blob([patched], { type: "text/javascript" });
    return URL.createObjectURL(blob);
  })()
)};

const _duoFmt = async function duoFmt(entryBlobUrl){return(
  await import(entryBlobUrl)
)};

const _stamps = function stamps(duoFmt){return(
  [7, 42, 1234].map(duoFmt.stamp)
)};

export default function define(runtime, observer) {
  const main = runtime.module();
  const $def = (pid, name, deps, fn) => {
    main.variable(observer(name)).define(name, deps, fn).pid = pid;
  };
  const fileAttachments = new Map(["index.js","pad.js"].map((name) => {
    const module_name = "@user/stamper";
    const {status, mime, bytes} = window.lopecode.contentSync(module_name + "/" + encodeURIComponent(name));
    const blob_url = URL.createObjectURL(new Blob([bytes], { type: mime}));
    return [name, {url: blob_url, mimeType: mime}]
  }));
  main.builtin("FileAttachment", runtime.fileAttachments(name => fileAttachments.get(name)));

  $def("_intro", "intro", ["md"], _intro);
  $def("_padBlobUrl", "padBlobUrl", ["FileAttachment"], _padBlobUrl);
  $def("_entryBlobUrl", "entryBlobUrl", ["FileAttachment", "padBlobUrl"], _entryBlobUrl);
  $def("_duoFmt", "duoFmt", ["entryBlobUrl"], _duoFmt);
  $def("_stamps", "stamps", ["duoFmt"], _stamps);
